from bioblend.galaxy import GalaxyInstance
from pathlib import Path
import os, json
key=Path(os.environ['GALAXY_API_KEY_FILE']).read_text().strip()
gi=GalaxyInstance(url=os.environ.get('GALAXY_URL','https://usegalaxy.org'), key=key)
t=gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0', io_details=True, link_details=False)
# Print conditional selectors/options and any case names containing branch/long
def walk(x, path=''):
    if isinstance(x, dict):
        if x.get('model_class')=='Conditional':
            tp=x.get('test_param',{})
            print('CONDITIONAL', path+'/'+x.get('name',''), 'selector', tp.get('name'), 'default', tp.get('value'))
            print('OPTIONS', tp.get('options'))
            for c in x.get('cases',[]):
                print('  CASE', c.get('value'), 'inputs', [i.get('name') for i in c.get('inputs',[])])
        for k,v in x.items(): walk(v, path+'/'+str(k))
    elif isinstance(x, list):
        for i,v in enumerate(x): walk(v, path+f'[{i}]')
walk(t.get('inputs'))
print('OUTPUTS')
print(json.dumps(t.get('outputs'), indent=2))
PY"

